z['rank']=np.arange(1,len(z)+1);z['BH_raw_step']=z.P*len(z)/z['rank'];z['BH_recomputed']=np.minimum.accumulate(z.BH_raw_step.to_numpy()[::-1])[::-1].clip(0,1);assert np.allclose(z.BH_recomputed,z.FDR);assert np.allclose(false_discovery_control(z.P),z.FDR)
z.to_csv(O/'evidence/SKIL_FDR_full_family_audit.tsv',sep='\t',index=False)
