q={'family':fam,'m':len(z),'programs':sorted(z.program.unique()),'gene_state_pairs':len(z[['gene','scope']].drop_duplicates()),'n_unique_genes':z.gene.nunique(),'scopes':z.groupby('scope').size().to_dict(),'unrelated_analysis_types_in_family':False,'duplicate_hypotheses':int(z.duplicated(['scope','gene','program']).sum()),'max_BH_difference':float(abs(z.BH_recomputed-z.FDR).max()),'P_SKIL_TAct':float(z[(z.gene=='SKIL')&(z.program=='TAct')].P.iloc[0]),'FDR_SKIL_TAct':float(z[(z.gene=='SKIL')&(z.program=='TAct')].FDR.iloc[0]),'minimum_adjustment_step':z.loc[z.BH_raw_step.idxmin(),['rank','P','BH_raw_step']].to_dict(),'interpretation':'original exploratory candidate-phenotype screen pooled across predeclared candidate-state pairs and 5 phenotype modules; no DE, pathway enrichment, ligand/TF, damage, alternative-model or external-cohort tests mixed in; preserve original family, no result-driven narrowing'}
(O/'evidence/FDR_audit.json').write_text(json.dumps(q,ensure_ascii=False,indent=2),encoding='utf-8')